Below is a reusable Terraform module for the requested **S3 bucket, PostgreSQL RDS instance, and IAM role for Kubernetes service accounts (IRSA)**. It supports:

- S3 versioning, AES-256 encryption, and public-access blocking
- Production cross-region replication to `us-west-2`
- Private RDS with deletion protection, backups, encryption, and AWS-managed credentials
- Least-privilege IAM access to the application bucket
- OIDC trust restricted to one Kubernetes service account
- Independently deployable dev/prod environments using separate state and tfvars

> The broader canonical scenario also mentions EKS and HTTPS exposure. Those resources are not included because the requested module is specifically bucket + RDS + IAM. The module accepts an existing EKS OIDC provider.

## Directory structure

```text
terraform/
├── modules/
│   └── app-data/
│       ├── main.tf
│       ├── variables.tf
│       ├── outputs.tf
│       └── versions.tf
├── environments/
│   ├── dev.tfvars
│   └── prod.tfvars
├── main.tf
├── variables.tf
├── outputs.tf
├── providers.tf
├── versions.tf
└── backend.hcl.example
```

# Reusable module

## `modules/app-data/versions.tf`

```hcl
terraform {
  required_version = ">= 1.6.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"

      configuration_aliases = [
        aws.replica
      ]
    }
  }
}
```

## `modules/app-data/variables.tf`

```hcl
variable "name" {
  description = "Base name used for resources."
  type        = string
}

variable "environment" {
  description = "Deployment environment."
  type        = string

  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "environment must be dev or prod."
  }
}

variable "tags" {
  description = "Additional resource tags."
  type        = map(string)
  default     = {}
}

variable "bucket_name" {
  description = "Globally unique name for the application assets bucket."
  type        = string
}

variable "enable_replication" {
  description = "Replicate the assets bucket to the replica provider region."
  type        = bool
  default     = false
}

variable "replica_bucket_name" {
  description = "Globally unique destination bucket name. Required when replication is enabled."
  type        = string
  default     = null

  validation {
    condition = (
      !var.enable_replication ||
      (var.replica_bucket_name != null && length(var.replica_bucket_name) > 0)
    )
    error_message = "replica_bucket_name is required when enable_replication is true."
  }
}

variable "db_name" {
  description = "Initial PostgreSQL database name."
  type        = string
  default     = "app"
}

variable "db_username" {
  description = "PostgreSQL master username. The password is managed by AWS Secrets Manager."
  type        = string
  default     = "appadmin"
}

variable "db_instance_class" {
  description = "RDS instance class."
  type        = string
}

variable "db_allocated_storage" {
  description = "Initial RDS storage in GiB."
  type        = number
  default     = 20
}

variable "db_max_allocated_storage" {
  description = "Maximum RDS autoscaled storage in GiB."
  type        = number
  default     = 100
}

variable "db_multi_az" {
  description = "Whether RDS should be deployed across multiple availability zones."
  type        = bool
}

variable "db_storage_encrypted" {
  description = "Whether RDS storage is encrypted."
  type        = bool
  default     = true
}

variable "db_kms_key_id" {
  description = "Optional KMS key ARN for RDS and its managed master-user secret."
  type        = string
  default     = null
}

variable "db_subnet_ids" {
  description = "Private subnet IDs for the RDS subnet group."
  type        = list(string)

  validation {
    condition     = length(var.db_subnet_ids) >= 2
    error_message = "At least two DB subnet IDs are required."
  }
}

variable "db_security_group_ids" {
  description = "Security group IDs attached to RDS."
  type        = list(string)

  validation {
    condition     = length(var.db_security_group_ids) > 0
    error_message = "At least one DB security group ID is required."
  }
}

variable "db_backup_retention_period" {
  description = "Number of days to retain automated RDS backups."
  type        = number
  default     = 7

  validation {
    condition     = var.db_backup_retention_period >= 7
    error_message = "Backup retention must be at least 7 days."
  }
}

variable "db_deletion_protection" {
  description = "Protect the RDS instance from deletion."
  type        = bool
  default     = true

  validation {
    condition     = var.db_deletion_protection
    error_message = "Deletion protection must remain enabled."
  }
}

variable "oidc_provider_arn" {
  description = "ARN of the EKS IAM OIDC provider."
  type        = string
}

variable "oidc_provider_url" {
  description = "EKS OIDC issuer URL, with or without the https:// prefix."
  type        = string
}

variable "kubernetes_namespace" {
  description = "Namespace containing the service account."
  type        = string
}

variable "kubernetes_service_account" {
  description = "Name of the Kubernetes service account."
  type        = string
}
```

## `modules/app-data/main.tf`

```hcl
locals {
  resource_name = "${var.name}-${var.environment}"

  oidc_provider_host = trimprefix(var.oidc_provider_url, "https://")

  common_tags = merge(
    {
      Application = var.name
      Environment = var.environment
      ManagedBy   = "Terraform"
    },
    var.tags
  )
}

# -----------------------------------------------------------------------------
# Primary application assets bucket
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "assets" {
  bucket = var.bucket_name

  tags = merge(local.common_tags, {
    Name = "${local.resource_name}-assets"
  })
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket = aws_s3_bucket.assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "assets" {
  bucket = aws_s3_bucket.assets.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_policy" "assets_tls_only" {
  bucket = aws_s3_bucket.assets.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.assets.arn,
          "${aws_s3_bucket.assets.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.assets]
}

# -----------------------------------------------------------------------------
# Optional production replication bucket
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica

  bucket = var.replica_bucket_name

  tags = merge(local.common_tags, {
    Name = "${local.resource_name}-assets-replica"
  })
}

resource "aws_s3_bucket_versioning" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_policy" "replica_tls_only" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.replica[0].arn,
          "${aws_s3_bucket.replica[0].arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Replication IAM role and configuration
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "replication_assume_role" {
  count = var.enable_replication ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  count = var.enable_replication ? 1 : 0

  name               = "${local.resource_name}-s3-replication"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role[0].json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "replication" {
  count = var.enable_replication ? 1 : 0

  statement {
    sid = "ReadSourceBucketConfiguration"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket"
    ]

    resources = [aws_s3_bucket.assets.arn]
  }

  statement {
    sid = "ReadSourceObjectVersions"

    actions = [
      "s3:GetObjectVersion",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging"
    ]

    resources = ["${aws_s3_bucket.assets.arn}/*"]
  }

  statement {
    sid = "ReplicateToDestination"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags"
    ]

    resources = ["${aws_s3_bucket.replica[0].arn}/*"]
  }
}

resource "aws_iam_role_policy" "replication" {
  count = var.enable_replication ? 1 : 0

  name   = "${local.resource_name}-s3-replication"
  role   = aws_iam_role.replication[0].id
  policy = data.aws_iam_policy_document.replication[0].json
}

resource "aws_s3_bucket_replication_configuration" "assets" {
  count = var.enable_replication ? 1 : 0

  bucket = aws_s3_bucket.assets.id
  role   = aws_iam_role.replication[0].arn

  rule {
    id     = "replicate-all-assets"
    status = "Enabled"

    filter {}

    destination {
      bucket        = aws_s3_bucket.replica[0].arn
      storage_class = "STANDARD"
    }

    delete_marker_replication {
      status = "Enabled"
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.assets,
    aws_s3_bucket_versioning.replica,
    aws_iam_role_policy.replication
  ]
}

# -----------------------------------------------------------------------------
# PostgreSQL RDS
# -----------------------------------------------------------------------------

resource "aws_db_subnet_group" "app" {
  name       = "${local.resource_name}-db"
  subnet_ids = var.db_subnet_ids

  tags = merge(local.common_tags, {
    Name = "${local.resource_name}-db"
  })
}

resource "aws_db_instance" "postgres" {
  identifier = "${local.resource_name}-postgres"

  engine         = "postgres"
  engine_version = "16"

  instance_class        = var.db_instance_class
  allocated_storage     = var.db_allocated_storage
  max_allocated_storage = var.db_max_allocated_storage
  storage_type          = "gp3"
  storage_encrypted     = var.db_storage_encrypted
  kms_key_id            = var.db_kms_key_id

  db_name  = var.db_name
  username = var.db_username
  port     = 5432

  # AWS generates and stores the password in Secrets Manager. No database
  # password is supplied through tfvars or committed to Git.
  manage_master_user_password   = true
  master_user_secret_kms_key_id = var.db_kms_key_id

  db_subnet_group_name   = aws_db_subnet_group.app.name
  vpc_security_group_ids = var.db_security_group_ids
  publicly_accessible    = false
  multi_az               = var.db_multi_az

  backup_retention_period = var.db_backup_retention_period
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:04:00-sun:05:00"

  deletion_protection = var.db_deletion_protection
  skip_final_snapshot  = false
  final_snapshot_identifier = (
    "${local.resource_name}-postgres-final"
  )

  auto_minor_version_upgrade = true
  copy_tags_to_snapshot       = true

  enabled_cloudwatch_logs_exports = [
    "postgresql",
    "upgrade"
  ]

  tags = merge(local.common_tags, {
    Name = "${local.resource_name}-postgres"
  })
}

# -----------------------------------------------------------------------------
# IAM role for Kubernetes service account
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "service_account_assume_role" {
  statement {
    sid     = "AllowSpecificKubernetesServiceAccount"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [var.oidc_provider_arn]
    }

    condition {
      test     = "StringEquals"
      variable = "${local.oidc_provider_host}:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "${local.oidc_provider_host}:sub"
      values = [
        "system:serviceaccount:${var.kubernetes_namespace}:${var.kubernetes_service_account}"
      ]
    }
  }
}

resource "aws_iam_role" "service_account" {
  name               = "${local.resource_name}-service-account"
  assume_role_policy = data.aws_iam_policy_document.service_account_assume_role.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "service_account" {
  statement {
    sid = "ListApplicationAssets"

    actions = [
      "s3:ListBucket"
    ]

    resources = [aws_s3_bucket.assets.arn]
  }

  statement {
    sid = "ReadWriteApplicationAssets"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:DeleteObject"
    ]

    resources = ["${aws_s3_bucket.assets.arn}/*"]
  }

  statement {
    sid = "DescribeManagedDatabaseSecret"

    actions = [
      "secretsmanager:DescribeSecret"
    ]

    resources = [
      aws_db_instance.postgres.master_user_secret[0].secret_arn
    ]
  }

  statement {
    sid = "ReadManagedDatabaseSecret"

    actions = [
      "secretsmanager:GetSecretValue"
    ]

    resources = [
      aws_db_instance.postgres.master_user_secret[0].secret_arn
    ]
  }
}

resource "aws_iam_role_policy" "service_account" {
  name   = "${local.resource_name}-application"
  role   = aws_iam_role.service_account.id
  policy = data.aws_iam_policy_document.service_account.json
}
```

## `modules/app-data/outputs.tf`

```hcl
output "assets_bucket_name" {
  description = "Name of the primary application assets bucket."
  value       = aws_s3_bucket.assets.id
}

output "assets_bucket_arn" {
  description = "ARN of the primary application assets bucket."
  value       = aws_s3_bucket.assets.arn
}

output "replica_bucket_name" {
  description = "Name of the replica bucket, if enabled."
  value       = try(aws_s3_bucket.replica[0].id, null)
}

output "db_instance_identifier" {
  description = "RDS instance identifier."
  value       = aws_db_instance.postgres.identifier
}

output "db_endpoint" {
  description = "RDS hostname without the port."
  value       = aws_db_instance.postgres.address
}

output "db_port" {
  description = "RDS PostgreSQL port."
  value       = aws_db_instance.postgres.port
}

output "db_name" {
  description = "Initial PostgreSQL database name."
  value       = aws_db_instance.postgres.db_name
}

output "db_master_secret_arn" {
  description = "ARN of the AWS-managed Secrets Manager master credential secret."
  value       = aws_db_instance.postgres.master_user_secret[0].secret_arn
}

output "service_account_role_arn" {
  description = "IAM role ARN to place in the Kubernetes service account annotation."
  value       = aws_iam_role.service_account.arn
}
```

# Root configuration

## `versions.tf`

```hcl
terraform {
  required_version = ">= 1.6.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }

  # Configure with:
  # terraform init -backend-config=backend-dev.hcl
  # or:
  # terraform init -backend-config=backend-prod.hcl
  backend "s3" {}
}
```

## `providers.tf`

```hcl
provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Application = var.name
      Environment = var.environment
      ManagedBy   = "Terraform"
    }
  }
}

provider "aws" {
  alias  = "replica"
  region = var.replica_region

  default_tags {
    tags = {
      Application = var.name
      Environment = var.environment
      ManagedBy   = "Terraform"
    }
  }
}
```

## `variables.tf`

```hcl
variable "name" {
  type    = string
  default = "webapp"
}

variable "environment" {
  type = string

  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "environment must be dev or prod."
  }
}

variable "aws_region" {
  type = string
}

variable "replica_region" {
  type    = string
  default = "us-west-2"
}

variable "bucket_name" {
  type = string
}

variable "enable_replication" {
  type    = bool
  default = false
}

variable "replica_bucket_name" {
  type    = string
  default = null
}

variable "db_instance_class" {
  type = string
}

variable "db_multi_az" {
  type = bool
}

variable "db_subnet_ids" {
  type = list(string)
}

variable "db_security_group_ids" {
  type = list(string)
}

variable "oidc_provider_arn" {
  type = string
}

variable "oidc_provider_url" {
  type = string
}

variable "kubernetes_namespace" {
  type    = string
  default = "webapp"
}

variable "kubernetes_service_account" {
  type    = string
  default = "webapp"
}

variable "tags" {
  type    = map(string)
  default = {}
}
```

## `main.tf`

```hcl
module "app_data" {
  source = "./modules/app-data"

  providers = {
    aws         = aws
    aws.replica = aws.replica
  }

  name        = var.name
  environment = var.environment
  tags        = var.tags

  bucket_name         = var.bucket_name
  enable_replication  = var.enable_replication
  replica_bucket_name = var.replica_bucket_name

  db_name                    = "app"
  db_username                = "appadmin"
  db_instance_class          = var.db_instance_class
  db_multi_az                = var.db_multi_az
  db_storage_encrypted       = true
  db_backup_retention_period = 7
  db_deletion_protection     = true
  db_subnet_ids              = var.db_subnet_ids
  db_security_group_ids      = var.db_security_group_ids

  oidc_provider_arn          = var.oidc_provider_arn
  oidc_provider_url          = var.oidc_provider_url
  kubernetes_namespace       = var.kubernetes_namespace
  kubernetes_service_account = var.kubernetes_service_account
}
```

## `outputs.tf`

```hcl
output "assets_bucket_name" {
  value = module.app_data.assets_bucket_name
}

output "replica_bucket_name" {
  value = module.app_data.replica_bucket_name
}

output "db_endpoint" {
  value = module.app_data.db_endpoint
}

output "db_master_secret_arn" {
  value = module.app_data.db_master_secret_arn
}

output "service_account_role_arn" {
  value = module.app_data.service_account_role_arn
}
```

# Environment configuration

Replace example account IDs, subnet IDs, security groups, OIDC IDs, and globally unique bucket names.

## `environments/dev.tfvars`

```hcl
name        = "webapp"
environment = "dev"
aws_region  = "us-east-1"

bucket_name        = "example-company-webapp-assets-dev"
enable_replication = false

db_instance_class = "db.t3.micro"
db_multi_az       = false

db_subnet_ids = [
  "subnet-0123456789abcdef0",
  "subnet-0123456789abcdef1"
]

db_security_group_ids = [
  "sg-0123456789abcdef0"
]

oidc_provider_arn = "arn:aws:iam::111111111111:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/DEVEXAMPLE"
oidc_provider_url = "https://oidc.eks.us-east-1.amazonaws.com/id/DEVEXAMPLE"

kubernetes_namespace       = "webapp"
kubernetes_service_account = "webapp"

